// DB-only partial unique index ux_e_booklet_paid_code_one_counted_redemption enforces one counted paid-code redemption per access code.\n  @@unique([access_code_id, student_id])\n  @@index([booklet_instance_id, student_id], map: \"ix_e_booklet_code_redemptions_instance_student\")\n  @@index([purchase_id], map: \"ix_e_booklet_code_redemptions_purchase\")\n  @@index([counted_for_progress, redeemed_at], map: \"ix_e_booklet_code_redemptions_progress\")\n}\n\nmodel e_booklet_access {\n  id                  Int                          @id @default(autoincrement())\n  booklet_instance_id Int\n  user_id             Int\n  role                e_booklet_access_role_enum\n  source_invite_id    Int?\n  access_source       String?                      @db.VarChar(40)\n  terms_accepted_at   DateTime?                    @db.Timestamp(6)\n  terms_version       String?                      @db.VarChar(50)\n  status              e_booklet_access_status_enum @default(active)\n  granted_at          DateTime?                    @default(now()) @db.Timestamp(6)\n  revoked_at          DateTime?                    @db.Timestamp(6)\n\n  booklet_instance        e_booklet_instances                 @relation(fields: [booklet_instance_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  user                    users                               @relation(fields: [user_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  source_invite           e_booklet_invites?                  @relation(fields: [source_invite_id], references: [id], onDelete: SetNull, onUpdate: NoAction)\n  student_purchase_links  e_booklet_student_purchase_links[]\n  access_code_redemptions e_booklet_access_code_redemptions[]\n\n  @@unique([booklet_instance_id, user_id, role])\n  @@index([user_id, role, status], map: \"ix_e_booklet_access_user_role_status\")\n  @@index([booklet_instance_id, role, status], map: \"ix_e_booklet_access_instance_role_status\")\n}\n\nmodel e_booklet_invites {\n  id                     Int                          @id @default(autoincrement())\n  booklet_instance_id    Int\n  teacher_id             Int\n  token_hash             String                       @unique @db.VarChar(128)\n  share_token_ciphertext String?                      @db.Text\n  passcode_hash          String?                      @db.VarChar(128)\n  passcode_ciphertext    String?                      @db.Text\n  passcode_hint          String?                      @db.VarChar(20)\n  max_uses               Int?\n  used_count             Int                          @default(0)\n  expires_at             DateTime?                    @db.Timestamp(6)\n  status                 e_booklet_invite_status_enum @default(active)\n  created_at             DateTime?                    @default(now()) @db.Timestamp(6)\n\n  booklet_instance       e_booklet_instances                @relation(fields: [booklet_instance_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  teacher                users                              @relation(\"EBookletInviteTeacher\", fields: [teacher_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  access_records         e_booklet_access[]\n  redemptions            e_booklet_invite_redemptions[]\n  student_purchase_links e_booklet_student_purchase_links[]\n\n  @@index([booklet_instance_id, status], map: \"ix_e_booklet_invites_instance_status\")\n  @@index([teacher_id, status], map: \"ix_e_booklet_invites_teacher_status\")\n}\n\nmodel e_booklet_devices {\n  id                  Int       @id @default(autoincrement())\n  booklet_instance_id Int\n  user_id             Int\n  device_fingerprint  String    @db.VarChar(128)\n  device_label        String?   @db.VarChar(255)\n  user_agent          String?   @db.Text\n  ip_address          String?   @db.VarChar(64)\n  first_seen_at       DateTime? @default(now()) @db.Timestamp(6)\n  last_seen_at        DateTime? @db.Timestamp(6)\n  status              String    @default(\"active\") @db.VarChar(20)\n  reset_by_admin_id   Int?\n  reset_reason        String?   @db.Text\n\n  booklet_instance e_booklet_instances @relation(fields: [booklet_instance_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  user             users               @relation(fields: [user_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@unique([booklet_instance_id, user_id, device_fingerprint])\n  @@index([user_id, status])\n  @@index([booklet_instance_id, status])\n}\n\nmodel e_booklet_device_allowances {\n  id                  Int       @id @default(autoincrement())\n  booklet_instance_id Int\n  user_id             Int\n  allowed_devices     Int       @default(1)\n  updated_by_admin_id Int?\n  reason              String?   @db.Text\n  updated_at          DateTime? @db.Timestamp(6)\n\n  booklet_instance e_booklet_instances @relation(fields: [booklet_instance_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  user             users               @relation(fields: [user_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@unique([booklet_instance_id, user_id])\n  @@index([user_id])\n}\n\nmodel e_booklet_student_purchase_links {\n  id                       Int       @id @default(autoincrement())\n  purchase_id              Int       @unique\n  invite_id                Int\n  booklet_instance_id      Int\n  student_id               Int\n  access_id                Int?\n  marketing_price_snapshot Decimal   @db.Decimal(10, 2)\n  terms_accepted_at        DateTime? @db.Timestamp(6)\n  terms_version            String?   @db.VarChar(50)\n  created_at               DateTime? @default(now()) @db.Timestamp(6)\n  approved_at              DateTime? @db.Timestamp(6)\n\n  purchase         purchases           @relation(fields: [purchase_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  invite           e_booklet_invites   @relation(fields: [invite_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  booklet_instance e_booklet_instances @relation(fields: [booklet_instance_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  student          users               @relation(\"EBookletStudentPurchaseStudent\", fields: [student_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  access           e_booklet_access?   @relation(fields: [access_id], references: [id], onDelete: SetNull, onUpdate: NoAction)\n\n  @@index([booklet_instance_id, student_id])\n  @@index([invite_id, student_id])\n}\n\nmodel e_booklet_invite_redemptions {\n  id                  Int       @id @default(autoincrement())\n  invite_id           Int\n  booklet_instance_id Int\n  student_id          Int\n  redeemed_at         DateTime? @default(now()) @db.Timestamp(6)\n  ip_address          String?   @db.VarChar(64)\n  user_agent          String?   @db.Text\n\n  invite           e_booklet_invites   @relation(fields: [invite_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  booklet_instance e_booklet_instances @relation(fields: [booklet_instance_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  student          users               @relation(\"EBookletInviteRedemptionStudent\", fields: [student_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@unique([invite_id, student_id])\n  @@index([booklet_instance_id, student_id], map: \"ix_e_booklet_redemptions_instance_student\")\n}\n\nmodel e_booklet_file_assets {\n  id                Int                            @id @default(autoincrement())\n  owner_type        String                         @db.VarChar(50)\n  owner_id          Int?\n  file_type         e_booklet_file_type_enum\n  storage_key       String                         @unique @db.VarChar(500)\n  original_filename String                         @db.VarChar(255)\n  mime_type         String                         @db.VarChar(150)\n  size_bytes        Int\n  visibility        e_booklet_file_visibility_enum @default(private)\n  created_at    